    "grn_line_id": 16,
    "material_id": 16,
    "batch_number": "n",
    "quantity": 4326.41688,
    "uom_id": 16,
    "source_bin_id": 16,
    "destination_bin_id": 16,
    "strategy": "FIFO",
    "assigned_to": 16,
    "remarks": "architecto"
};

